if (i == -1 || str[i] == ' '){
for (int j = i + 1; j < caret; ++j){
reversed[pos++] = str[j]; 
}
if (i != -1) {
reversed[pos++] = ' '; 
}
caret = i;
} 
} 
printf("%s\n", reversed); 
} 
FIBEVERSE.C 
#include <stdlib.h> 
#include <string.h>
#include "fibonacci.h" 
#include "reverse.h" 
int main(int argc, char *argv[]) {
int i = 1; 
#ifdef FIBONACCI 
if (i < argc) { 
print_fib(atoi(argv[i])); 
i++; 
}
#endif 
#ifdef REVERSE 
if (i < argc) {
reverse(argv[i], strlen(argv[i]));
i++;
}
#endif 
return 0;
} 
